import{_ as a,o as t,c as o,a3 as i}from"./chunks/framework.DMtjdCb-.js";const d="/help/assets/offline-update.en.Cz4qlKNY.png",m=JSON.parse('{"title":"9. Updates and backups","description":"","frontmatter":{},"headers":[],"relativePath":"en/updates.md","filePath":"en/updates.md"}'),n={name:"en/updates.md"};function s(r,e,l,c,p,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_9-updates-and-backups" tabindex="-1">9. Updates and backups <a class="header-anchor" href="#_9-updates-and-backups" aria-label="Permalink to &quot;9. Updates and backups&quot;">​</a></h1><p>App updates retain settings, catalog data, and viewing records. Bangumi Archive is the title-data package and updates separately from the app.</p><h2 id="online-updates" tabindex="-1">Online updates <a class="header-anchor" href="#online-updates" aria-label="Permalink to &quot;Online updates&quot;">​</a></h2><ol><li>Open <strong>Settings → Updates</strong>.</li><li>Check for a release and read its notes.</li><li>Use the available update action, wait for the restart, then refresh.</li><li>Check the running version. Docker users can also redeploy with an updated image.</li></ol><h2 id="upload-an-offline-update" tabindex="-1">Upload an offline update <a class="header-anchor" href="#upload-an-offline-update" aria-label="Permalink to &quot;Upload an offline update&quot;">​</a></h2><p>From 0.5.1, the same page accepts an offline update package:</p><ol><li>Obtain a matching <code>.anm-update.zip</code> on a device that can download it.</li><li>Select and upload it in <strong>Settings → Updates</strong>.</li><li>Wait for validation, installation, and restart, then check the version.</li></ol><p><img src="'+d+'" alt="Offline updates: select the package for this deployment" loading="lazy"></p><table tabindex="0"><thead><tr><th>Deployment</th><th>Update package</th></tr></thead><tbody><tr><td>Windows release</td><td><code>AnimeMachine-version-windows.anm-update.zip</code></td></tr><tr><td>Docker</td><td><code>AnimeMachine-version-docker.anm-update.zip</code></td></tr></tbody></table><p>The ordinary <code>release-windows.zip</code> is a complete installation; the Docker <code>tar.gz</code> is an offline image. These differ from upload packages. A mismatched or invalid upload leaves the current working version in place.</p><h2 id="upgrade-docker-0-5-0-to-0-5-1" tabindex="-1">Upgrade Docker 0.5.0 to 0.5.1 <a class="header-anchor" href="#upgrade-docker-0-5-0-to-0-5-1" aria-label="Permalink to &quot;Upgrade Docker 0.5.0 to 0.5.1&quot;">​</a></h2><p>Download the offline image from <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a>. Choose <code>amd64</code> for Intel/AMD or <code>arm64</code> for ARM.</p><p>Version 0.5.0 has no upload control. Start with a local image upgrade:</p><ol><li>Upload <code>AnimeMachine-0.5.1-docker-linux-amd64.tar.gz</code> to the NAS. This image is for Intel/AMD; ARM devices need their matching architecture.</li><li>Import it in a terminal:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AnimeMachine-0.5.1-docker-linux-amd64.tar.gz</span></span></code></pre></div><ol start="3"><li>Set <code>ANM_IMAGE=animemachine:0.5.1</code> in the project&#39;s <code>.env</code>. For the default full stack, also set <code>TORRENT_COLLECTOR_IMAGE=animemachine:0.5.1</code>.</li><li>Run <code>docker compose up -d --pull never</code> there, refresh, and check the version.</li></ol><p>If your custom Compose file hard-codes image names, change the corresponding services&#39; <code>image</code> values. Keep mounts, environment settings, and data folders.</p><h2 id="replace-a-desktop-release-manually" tabindex="-1">Replace a desktop release manually <a class="header-anchor" href="#replace-a-desktop-release-manually" aria-label="Permalink to &quot;Replace a desktop release manually&quot;">​</a></h2><p>Stop the old app and extract the new package into a new folder. Copy <code>config.json</code>, <code>.env.local</code> if present, and the entire <code>data</code> folder from the old installation, then start the new one. Keep separately stored media accessible at its existing path.</p><h2 id="back-up-the-persistent-files" tabindex="-1">Back up the persistent files <a class="header-anchor" href="#back-up-the-persistent-files" aria-label="Permalink to &quot;Back up the persistent files&quot;">​</a></h2><p>Stop AnimeMachine before backing up settings and <code>data</code>. Back up media using your usual storage backup method.</p><table tabindex="0"><thead><tr><th>Deployment</th><th>Keep</th></tr></thead><tbody><tr><td>Desktop</td><td><code>config.json</code>, <code>.env.local</code> if present, and <code>data</code></td></tr><tr><td>Docker</td><td><code>compose.yaml</code>, <code>.env</code> if present, <code>config</code>, <code>data</code>, and custom mount settings</td></tr></tbody></table><p>Restore the same mappings and account data. Files such as <code>initial-admin.txt</code> and service password files contain account information; keep them with your protected backup.</p>',23)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
